CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TABLE tenants (id UUID PRIMARY KEY, name VARCHAR(180) NOT NULL, slug VARCHAR(80) UNIQUE NOT NULL, timezone VARCHAR(60) NOT NULL DEFAULT 'Asia/Kolkata', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE academic_years (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(40) NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, active BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), email VARCHAR(180) NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL, display_name VARCHAR(160) NOT NULL, active BOOLEAN NOT NULL DEFAULT true, UNIQUE (tenant_id, email));
CREATE TABLE classes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(80) NOT NULL);
CREATE TABLE sections (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), class_id UUID NOT NULL REFERENCES classes(id), name VARCHAR(30) NOT NULL);
CREATE TABLE students (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), admission_number VARCHAR(60) NOT NULL, display_name VARCHAR(160) NOT NULL, section_id UUID REFERENCES sections(id), date_of_birth DATE, active BOOLEAN NOT NULL DEFAULT true, UNIQUE (tenant_id, admission_number));
CREATE TABLE student_guardians (student_id UUID NOT NULL REFERENCES students(id), user_id UUID NOT NULL REFERENCES users(id), relation VARCHAR(40) NOT NULL, PRIMARY KEY(student_id, user_id));
CREATE TABLE subjects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(100) NOT NULL);
CREATE TABLE attendance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), student_id UUID NOT NULL REFERENCES students(id), attendance_date DATE NOT NULL, status VARCHAR(20) NOT NULL, marked_by UUID REFERENCES users(id), UNIQUE (tenant_id, student_id, attendance_date));
CREATE TABLE homework (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), title VARCHAR(200) NOT NULL, subject_id UUID REFERENCES subjects(id), section_id UUID REFERENCES sections(id), due_date DATE, created_by UUID REFERENCES users(id));
CREATE TABLE exams (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(160) NOT NULL, academic_year_id UUID REFERENCES academic_years(id));
CREATE TABLE results (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), exam_id UUID NOT NULL REFERENCES exams(id), student_id UUID NOT NULL REFERENCES students(id), subject_id UUID REFERENCES subjects(id), marks NUMERIC(6,2) NOT NULL, grade VARCHAR(8));
CREATE TABLE fee_structures (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(160) NOT NULL, amount NUMERIC(12,2) NOT NULL);
CREATE TABLE invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), student_id UUID NOT NULL REFERENCES students(id), invoice_number VARCHAR(60) NOT NULL, amount NUMERIC(12,2) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', due_date DATE, UNIQUE (tenant_id, invoice_number));
CREATE TABLE payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), invoice_id UUID NOT NULL REFERENCES invoices(id), amount NUMERIC(12,2) NOT NULL, provider_reference VARCHAR(120), status VARCHAR(20) NOT NULL, paid_at TIMESTAMPTZ);
CREATE TABLE announcements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), title VARCHAR(200) NOT NULL, body TEXT NOT NULL, audience VARCHAR(40) NOT NULL, published_at TIMESTAMPTZ, created_by UUID REFERENCES users(id));
CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), actor_id UUID, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id UUID, metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_students_tenant ON students(tenant_id); CREATE INDEX idx_attendance_tenant_date ON attendance(tenant_id, attendance_date); CREATE INDEX idx_invoices_tenant_status ON invoices(tenant_id, status); CREATE INDEX idx_audit_tenant_created ON audit_logs(tenant_id, created_at);
